                }
            }
        """ ;
    ] .

ex:rentedStudyResidenceConditionShape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The student must live in rented accommodation in the city of study, different from the principal residence, and neither the student nor a parent may own property in that city." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                FILTER NOT EXISTS {
                    ?this :hasCurrentResidence ?currentResidence .
                    ?currentResidence :residenceType "Rented" .
                    ?currentResidence :locatedIn ?studyCity .

                    ?this :hasEducation ?education .
                    ?education :cityOfStudy ?studyCity .

                    ?this :hasFamilyResidence ?familyResidence .
                    ?familyResidence :locatedIn ?principalResidenceCity .
                    FILTER (?principalResidenceCity != ?studyCity)

                    FILTER NOT EXISTS {
                        {
                            ?this :ownsRealEstate ?property .
                            ?property :propertyLocation ?studyCity .
                        }
                        UNION
                        {
                            ?this :hasParent ?parent .
                            ?parent :ownsRealEstate ?property .
                            ?property :propertyLocation ?studyCity .
                        }
                    }
                }
            }
        """ ;
    ] .

ex:minimumLeaseDurationConditionShape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The current residence lease has not been valid for at least six months." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                FILTER NOT EXISTS {
                    ?this :hasCurrentResidence ?residence .
                    ?residence :leaseStartDate ?startDate .
                    FILTER (
                        ((YEAR(now()) * 12 + MONTH(now())) -
                         (YEAR(?startDate) * 12 + MONTH(?startDate))) >= 6
                    )
                }
            }
        """ ;
    ] .

ex:residentialPropertyAreaLimitConditionShape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The total area of residential properties in municipalities with at least 3,000 inhabitants exceeds 200 square metres." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                {
                    SELECT ?this (SUM(?area) AS ?totalArea)
                    WHERE {
                        SELECT DISTINCT ?this ?property ?area
                        WHERE {
                            {
                                ?this :ownsRealEstate ?property .
                            }
                            UNION
                            {
                                ?this :hasParent ?parent .
                                ?parent :ownsRealEstate ?property .
                            }

                            ?property :propertyAreaM2 ?area .
                            ?property :propertyLocation ?municipality .
                            ?municipality :municipalityPopulation ?population .
                            FILTER (?population >= 3000)
                        }
                    }
                    GROUP BY ?this
                }
                FILTER (?totalArea > 200)
            }
        """ ;
    ] .

ex:familyIncomeThresholdConditionShape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The family's annual income for the preceding year exceeds the permitted threshold of €30,000 plus €3,000 for each dependent child beyond the first." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
            SELECT ?this
            WHERE {
                {
                    SELECT ?this (SUM(?amount) AS ?totalIncome)
                    WHERE {
                        SELECT DISTINCT ?this ?incomeRecord ?amount
                        WHERE {
                            {
                                ?this :hasIncome ?incomeRecord .
                            }
                            UNION
                            {
                                ?this :hasParent ?parent .
                                ?parent :hasIncome ?incomeRecord .
                            }

                            ?incomeRecord :amount ?amount .
                            ?incomeRecord :incomeYear ?incomeYear .
                            FILTER (
                                xsd:integer(SUBSTR(STR(?incomeYear), 1, 4)) =
                                (YEAR(now()) - 1)
                            )
                        }
                    }
                    GROUP BY ?this
                }
                {
                    SELECT ?this (COUNT(DISTINCT ?child) AS ?dependentChildren)
                    WHERE {
                        OPTIONAL {
                            ?this :hasParent ?parentForChild .
                            ?parentForChild :hasChild ?child .
                            ?child :isDependent true .
                        }
                    }
                    GROUP BY ?this
                }
                FILTER (
                    ?totalIncome >
                    (30000 + (3000 * IF(?dependentChildren > 1, ?dependentChildren - 1, 0)))
                )
            }
        """ ;
    ] .

ex:courseCompletionConditionShape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The student has not passed examinations in at least half of the courses of the preceding academic year." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                FILTER NOT EXISTS {
                    ?this :hasEducation ?education .
                    ?education :passedCoursesCount ?passedCourses .
                    ?education :totalCoursesCount ?totalCourses .
                    FILTER ((?passedCourses * 2) >= ?totalCourses)
                }
            }
        """ ;
    ] .

inputs.citizen_schema:
@prefix : <http://example.org/schema#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

# CORE ENTITY
:Person a rdfs:Class ;
    rdfs:comment "A human individual." .

:Applicant a rdfs:Class ;
    rdfs:subClassOf :Person ;
    rdfs:comment "A person actively applying for a public service. Used as the Focus Node for SHACL validation." .

#  Basic Attributes 
:citizenshipCountry a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range xsd:string ;
    rdfs:comment "ISO code (e.g., 'GR', 'FR')." .

:birthDate a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range xsd:date .

:isDependent a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range xsd:boolean ;
    rdfs:comment "Flag to explicitly mark a family member as a dependent." .

#  Relationships 
:hasParent a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range :Person .

:hasChild a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range :Person .

# RESIDENCE & HOUSING 
:Residence a rdfs:Class ;
    rdfs:comment "A place where a person lives, either rented or owned." .

:Municipality a rdfs:Class ;
    rdfs:comment "The city or administrative area of a residence." .

#  Residence Properties 
:hasCurrentResidence a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range :Residence ;
    rdfs:comment "Where the student is currently living." .

:hasFamilyResidence a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range :Residence ;
    rdfs:comment "The permanent home of the parents/family." .

:locatedIn a rdf:Property ;
    rdfs:domain :Residence ;
    rdfs:range :Municipality .

:residenceType a rdf:Property ;
    rdfs:domain :Residence ;
    rdfs:range xsd:string ;
    rdfs:comment "Values: 'Rented', 'Owned', 'Guest'." .

:leaseStartDate a rdf:Property ;
    rdfs:domain :Residence ;
    rdfs:range xsd:date ;
    rdfs:comment "If rented, when the lease started." .

# INCOME 
:IncomeRecord a rdfs:Class ;
    rdfs:comment "Financial data for a specific year." .

:hasIncome a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range :IncomeRecord .

:incomeYear a rdf:Property ;
    rdfs:domain :IncomeRecord ;
    rdfs:range xsd:gYear .

:amount a rdf:Property ;
    rdfs:domain :IncomeRecord ;
    rdfs:range xsd:decimal .

# REAL ESTATE ASSETS
:RealEstateProperty a rdfs:Class ;
    rdfs:comment "A distinct physical property owned by someone." .

:ownsRealEstate a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range :RealEstateProperty .

:propertyAreaM2 a rdf:Property ;
    rdfs:domain :RealEstateProperty ;
    rdfs:range xsd:decimal .

:propertyLocation a rdf:Property ;
    rdfs:domain :RealEstateProperty ;
    rdfs:range :Municipality .

:municipalityPopulation a rdf:Property ;
    rdfs:domain :Municipality ;
    rdfs:range xsd:integer .

# EDUCATION
:EducationRecord a rdfs:Class ;
    rdfs:comment "Academic status for a specific period." .

:hasEducation a rdf:Property ;
    rdfs:domain :Person ;
    rdfs:range :EducationRecord .

:cityOfStudy a rdf:Property ;
    rdfs:domain :EducationRecord ;
    rdfs:range :Municipality ;
    rdfs:comment "Links the education record to the City/Municipality of the University." .

:hasValidAcademicID a rdf:Property ;
    rdfs:domain :EducationRecord ;
    rdfs:range xsd:boolean .

:passedCoursesCount a rdf:Property ;
    rdfs:domain :EducationRecord ;
    rdfs:range xsd:integer .

:totalCoursesCount a rdf:Property ;
    rdfs:domain :EducationRecord ;
    rdfs:range xsd:integer .

