        "related_paths": [
          {
            "path": [
              "hasParent",
              "hasChild",
              "isDependent"
            ],
            "datatype": "xsd:boolean"
          }
        ]
      }
    ]
  },
  {
    "name": "course_completion_condition",
    "desc": "The student must have successfully passed examinations in at least half of the courses of the preceding academic year for which the allowance is requested.",
    "constrains": [
      {
        "name": "passed_courses_count",
        "related_paths": [
          {
            "path": [
              "hasEducation",
              "passedCoursesCount"
            ],
            "datatype": "xsd:integer"
          }
        ]
      },
      {
        "name": "total_courses_count",
        "related_paths": [
          {
            "path": [
              "hasEducation",
              "totalCoursesCount"
            ],
            "datatype": "xsd:integer"
          }
        ]
      }
    ]
  },
  {
    "name": "parent_beneficiary_afm_condition",
    "desc": "Where the parent is the beneficiary, the application must state the taxpayer identification number (AFM) of the student and of the parent on whom the student is dependent. For divorced or separated parents, the beneficiary is the parent on whom the student is dependent.",
    "constrains": []
  },
  {
    "name": "parent_tax_return_filing_condition",
    "desc": "The relevant parent must have filed an income tax return for the year in which the housing-allowance application is submitted.",
    "constrains": []
  },
  {
    "name": "exceptional_student_beneficiary_condition",
    "desc": "The student may exceptionally be the beneficiary if they are orphaned by both parents; have parents residing abroad; are over 25 years old; or are required to file an income tax return and are not considered a dependent member under Article 11 of Law 4172/2013. In this case, the student declares only their spouse’s AFM, if applicable.",
    "constrains": [
      {
        "name": "student_birth_date",
        "related_paths": [
          {
            "path": [
              "birthDate"
            ],
            "datatype": "xsd:date"
          }
        ]
      },
      {
        "name": "student_dependency_status",
        "related_paths": [
          {
            "path": [
              "isDependent"
            ],
            "datatype": "xsd:boolean"
          }
        ]
      }
    ]
  },
  {
    "name": "cohabiting_student_eligibility_condition",
    "desc": "For the cohabitation-based allowance, the cohabiting person must be an undergraduate student at a higher education institution pursuing their first degree and must not have exceeded the study duration, in semesters, required by the curriculum to obtain that degree.",
    "constrains": []
  },
  {
    "name": "cohabitation_same_study_location_condition",
    "desc": "For the cohabitation-based allowance, the student and the cohabiting student must study in the same city or regional unit.",
    "constrains": []
  },
  {
    "name": "cohabiting_student_degree_and_duration_condition",
    "desc": "The cohabiting student must not hold another higher-education degree and must not have exceeded the maximum study-period limit in semesters provided by the Study Regulations.",
    "constrains": []
  },
  {
    "name": "cohabitation_tenant_afm_or_dependency_condition",
    "desc": "For the cohabitation-based allowance, the AFM declared as tenant on behalf of the other student must match the cohabiting student’s AFM, or the cohabiting student must include the student as a dependent child in their tax return.",
    "constrains": []
  },
  {
    "name": "cohabitation_lease_tenant_afm_condition",
    "desc": "For the cohabitation-based allowance, the lease submitted with the application must list as tenant the AFM declared for the cohabiting student.",
    "constrains": []
  }
]

inputs.shacl_shapes:
@prefix : <http://example.org/schema#> .
@prefix ex: <http://example.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .

ex:nationalityConditionShape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:property [
        sh:path :citizenshipCountry ;
        sh:minCount 1 ;
        sh:in (
            "GR"
            "AT" "BE" "BG" "HR" "CY" "CZ" "DK" "EE" "FI"
            "FR" "DE" "EL" "HU" "IE" "IT" "LV" "LT" "LU"
            "MT" "NL" "PL" "PT" "RO" "SK" "SI" "ES" "SE"
        ) ;
        sh:message "The student must be a Greek national or a national of a European Union Member State." ;
    ] .

ex:validAcademicIdentityCardConditionShape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The student does not hold a valid academic identity card." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                FILTER NOT EXISTS {
                    ?this :hasEducation ?education .
                    ?education :hasValidAcademicID true .
                }
            }
        """ ;
    ] .

ex:rentedStudyResidenceConditionShape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The student must live in rented accommodation in the city of study, different from the principal residence, and neither the student nor a parent may own property in that city." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                FILTER NOT EXISTS {
                    ?this :hasCurrentResidence ?currentResidence .
                    ?currentResidence :residenceType "Rented" .
                    ?currentResidence :locatedIn ?studyCity .

                    ?this :hasEducation ?education .
                    ?education :cityOfStudy ?studyCity .

                    ?this :hasFamilyResidence ?familyResidence .
                    ?familyResidence :locatedIn ?principalResidenceCity .
                    FILTER (?principalResidenceCity != ?studyCity)

                    FILTER NOT EXISTS {
                        {
                            ?this :ownsRealEstate ?property .
                            ?property :propertyLocation ?studyCity .
                        }
                        UNION
                        {
                            ?this :hasParent ?parent .
                            ?parent :ownsRealEstate ?property .
                            ?property :propertyLocation ?studyCity .
                        }
                    }
                }
            }
        """ ;
    ] .

ex:minimumLeaseDurationConditionShape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The current residence lease has not been valid for at least six months." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                FILTER NOT EXISTS {
                    ?this :hasCurrentResidence ?residence .
                    ?residence :leaseStartDate ?startDate .
                    FILTER (
                        ((YEAR(now()) * 12 + MONTH(now())) -
                         (YEAR(?startDate) * 12 + MONTH(?startDate))) >= 6
                    )
                }
            }
        """ ;
    ] .

ex:residentialPropertyAreaLimitConditionShape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The total area of residential properties in municipalities with at least 3,000 inhabitants exceeds 200 square metres." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                {
                    SELECT ?this (SUM(?area) AS ?totalArea)
                    WHERE {
                        SELECT DISTINCT ?this ?property ?area
                        WHERE {
                            {
                                ?this :ownsRealEstate ?property .
                            }
                            UNION
                            {
                                ?this :hasParent ?parent .
                                ?parent :ownsRealEstate ?property .
                            }

                            ?property :propertyAreaM2 ?area .
                            ?property :propertyLocation ?municipality .
                            ?municipality :municipalityPopulation ?population .
                            FILTER (?population >= 3000)
                        }
                    }
                    GROUP BY ?this
                }
                FILTER (?totalArea > 200)
            }
        """ ;
    ] .

ex:familyIncomeThresholdConditionShape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The family's annual income exceeds the permitted threshold of €30,000 plus €3,000 for each dependent child beyond the first." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                {
                    SELECT ?this (SUM(?amount) AS ?totalIncome)
                    WHERE {
                        SELECT DISTINCT ?this ?incomeRecord ?amount
                        WHERE {
                            {
                                ?this :hasIncome ?incomeRecord .
                            }
                            UNION
                            {
                                ?this :hasParent ?parent .
                                ?parent :hasIncome ?incomeRecord .
                            }

                            ?incomeRecord :amount ?amount .
                        }
                    }
                    GROUP BY ?this
                }

                {
                    SELECT ?this (COUNT(DISTINCT ?child) AS ?dependentChildren)
                    WHERE {
                        ?this a :Applicant .

                        OPTIONAL {
                            ?this :hasParent ?parentForChild .
                            ?parentForChild :hasChild ?child .
                            ?child :isDependent true .
                        }
                    }
                    GROUP BY ?this
                }

                FILTER (
                    ?totalIncome >
                    (30000 + (3000 * IF(?dependentChildren > 1, ?dependentChildren - 1, 0)))
                )
            }
        """ ;
    ] .

ex:courseCompletionConditionShape
    a sh:NodeShape ;
    sh:targetClass :Applicant ;
    sh:sparql [
        a sh:SPARQLConstraint ;
        sh:message "The student has not passed examinations in at least half of the courses of the preceding academic year." ;
        sh:select """
            PREFIX : <http://example.org/schema#>
            SELECT ?this
            WHERE {
                FILTER NOT EXISTS {
                    ?this :hasEducation ?education .
                    ?education :passedCoursesCount ?passedCourses .
                    ?education :totalCoursesCount ?totalCourses .
                    FILTER ((?passedCourses * 2) >= ?totalCourses)
                }
            }
        """ ;
    ] .
